//! Original untagged call errors over the one issued body/visitor.
use super::SourceSnapshot;use dm_analysis::{checks_proc_visibility::{Finding,Findings},check_policy::DiagnosticSeverity};use serde::{Serialize,Serializer,ser::{SerializeSeq,SerializeStruct}};use std::{fmt,io::{self,Write},path::Path};
struct Note<'a>(&'a dm_analysis::checks::Note);impl fmt::Display for Note<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{if let Some(source)=&self.0.source{write!(f,"{}:{}: {}",source.line,source.byte_column,self.0.message)}else{f.write_str(&self.0.message)}}}impl Serialize for Note<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{s.collect_str(self)}}
struct Notes<'a>(&'a[dm_analysis::checks::Note]);impl Serialize for Notes<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut out=s.serialize_seq(Some(self.0.len()))?;for note in self.0{out.serialize_element(&Note(note))?;}out.end()}}
struct Row<'a>(Finding<'a>);impl Serialize for Row<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{use serde::ser::Error;let row=self.0.diagnostic();let point=self.0.borrowed_reported_point().map_err(S::Error::custom)?;let(path,line,column)=point.coordinates();let synthetic=self.0.is_parser_synthetic();let span=(!synthetic).then_some([row.span.start,row.span.end]);let expression=(!synthetic).then_some([row.expression_span.start,row.expression_span.end]);let mut out=s.serialize_struct("OriginalCallArgumentDiagnostic",10)?;out.serialize_field("family",row.family)?;out.serialize_field("severity","error")?;out.serialize_field("file",path)?;out.serialize_field("line",&line)?;out.serialize_field("column",&column)?;out.serialize_field("location_kind",if synthetic{"parser_synthetic"}else{"source"})?;out.serialize_field("expanded_span",&span)?;out.serialize_field("expression_span",&expression)?;out.serialize_field("message",&row.message)?;out.serialize_field("notes",&Notes(&row.notes))?;out.end()}}
struct Rows<'a>(&'a Findings<'a>);impl Serialize for Rows<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut out=s.serialize_seq(Some(self.0.iter().len()))?;for row in self.0.iter(){out.serialize_element(&Row(row))?;}out.end()}}
struct Revision(u128);impl fmt::Display for Revision{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{:032x}",self.0)}}impl Serialize for Revision{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{s.collect_str(self)}}
#[derive(Serialize)]struct Envelope<'a>{row:&'static str,schema:&'static str,semantic_revision:Revision,source_revision:Revision,policy_revision:Revision,ordinal:u32,family:&'static str,environment:&'a Path,configuration:&'a Path,configuration_explicit:bool,configuration_present:bool,configuration_schema:&'static str,full_checker_parity:bool,declaration_profile:&'static str,native_declaration_error_count:usize,diagnostics:Rows<'a>}
impl SourceSnapshot{pub(super) fn write_original_call_arguments_using(&self,ordinal:u32,environment:&Path,tree:&dm_tree::SemanticTree,capture:&crate::runner_host::policy_capture::CapturedPolicyInputs,loaded:&dm_analysis::check_configuration::Loaded,output:&mut impl Write)->io::Result<()>{
 crate::daemon::control::checkpoint()?;let archive=capture.policy().archive();let db=self.native_raw_queries.as_ref().ok_or_else(||io::Error::other("argument findings require actual source QueryDb"))?;
 let resolver:&dyn dm_ir::Resolver=if let Some(receipt)=&self.diagnostic_declarations{if !receipt.authenticates(tree)||!self.matches_tree(tree){return Err(io::Error::other("argument diagnostic owner is foreign"))}tree}else{self.resolved.as_ref().ok_or_else(||io::Error::other("argument findings require actual retained semantic host"))?.checker_resolver(tree)?};
 if !self.matches_tree(tree)||!archive.matches_tree(tree)||!archive.uses_body_queries(db.as_ref()){return Err(io::Error::other("argument source archive/tree/Db owner differs"))}
 let profile=tree.checker_builtin_profile().ok_or_else(||io::Error::other("argument findings need actual pinned builtin profile"))?;
 let body=archive.parse_checked(ordinal as usize).map_err(|failure|match failure{dm_tree::frontend::BodySyntaxFailure::Operational(actual)=>actual,dm_tree::frontend::BodySyntaxFailure::Syntax(error)=>io::Error::other(error.message)})?;
 // Original producers have no errortype. Observation keys cannot suppress or
 // re-severity either Error, independently of tagged kwargs-override checking.
 if loaded.policy.register(None,DiagnosticSeverity::Error)!=Some(DiagnosticSeverity::Error){return Err(io::Error::other("untagged argument Error registration changed"))}
 db.with_original_call_arguments(archive,&body,resolver,profile,||{crate::daemon::control::checkpoint()?;self.named_policy_capture(tree)?;Ok(())},|findings|{for row in findings.iter(){row.borrowed_reported_point().map_err(io::Error::other)?;}let envelope=Envelope{row:"source_native_configured_checker",schema:"dm-session-source-query-v1",semantic_revision:Revision(tree.identity()),source_revision:Revision(self.source_revision),policy_revision:Revision(self.policy_revision.ok_or_else(||io::Error::other("argument policy revision absent"))?),ordinal,family:"call_arguments",environment,configuration:&loaded.selected.path,configuration_explicit:loaded.selected.explicit,configuration_present:loaded.present,configuration_schema:"complete_pinned_checker_schema",full_checker_parity:false,declaration_profile:self.diagnostic_declarations.as_ref().map_or("strict-native-declarations",|r|r.profile()),native_declaration_error_count:self.diagnostic_declarations.as_ref().map_or(0,|r|r.errors().len()),diagnostics:Rows(findings)};serde_json::to_writer(&mut *output,&envelope).map_err(io::Error::from)?;output.write_all(b"\n")?;crate::daemon::control::checkpoint()?;self.named_policy_capture(tree)?;Ok(())})
}}
